<script setup>import {state} from '../../domain/prototypeStore.js';import {useRouter} from 'vue-router';const router=useRouter()</script>
<template><section class="page-stack"><div class="page-heading"><div class="module-icon">安</div><div><h2>综合安防</h2><p>查看设备运行状态和关联事件</p></div></div><div class="card-grid"><article v-for="d in state.devices" :key="d.id" class="panel"><h3>{{d.name}}</h3><p>{{d.type}} · {{d.location}}</p><strong>{{d.status}}</strong></article></div><article class="panel"><h3>当前告警</h3><div v-for="e in state.events.filter(x=>x.status!=='已关闭')" :key="e.id" class="alert-row"><span>{{e.title}} · {{e.status}}</span><button class="secondary-button" @click="router.push('/web/incidents')">查看事件</button></div></article></section></template>
